using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
namespace FishSandbox {
 public class SandboxVerification:MonoBehaviour {
  readonly List<string> results=new();int failed;FishingGame g;string output;bool finished;
  void Check(bool condition,string name){results.Add((condition?"PASS ":"FAIL ")+name);if(!condition){failed++;Debug.LogError("VERIFY FAILED: "+name);}}
  IEnumerator Start(){g=GetComponent<FishingGame>();output=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Evidence"));if(Application.isEditor)output=Path.GetFullPath(Path.Combine(Application.dataPath,"../Evidence"));Directory.CreateDirectory(output);yield return null;yield return null;try{RunLogic();}catch(Exception e){failed++;results.Add("FAIL Exception "+e);}
   yield return new WaitForSecondsRealtime(.5f);Check(g.body.transform.position.y>.8f&&g.body.transform.position.y<2,"Player rests on pier without falling through");var y=g.body.transform.position.y;g.vertical=7;yield return new WaitForSecondsRealtime(.25f);Check(g.body.transform.position.y>y+.6f,"Jump produces physical upward displacement");yield return new WaitForSecondsRealtime(1.2f);Check(g.body.transform.position.y>.8f&&g.body.transform.position.y<2,"Jump lands on pier");
   g.gifts.Clear();g.CancelFishing("Verification");g.bait=20;g.quickBite=1;g.SetTool(0);Check(g.CastAt(new Vector3(0,-.2f,40)),"Cast consumes bait and creates bobber");Check(g.bait==19&&g.floatBobber&&g.line.enabled,"Cast visual and bait state");yield return new WaitForSecondsRealtime(.3f);Check(g.fishing==FishingState.Biting,"Quick bite progresses through live Update");g.CastOrHook();Check(g.fishing==FishingState.Reeling,"Hook transitions to reeling");var before=g.bag.Count;g.lineGuard=1;float elapsed=0;while(g.fishing==FishingState.Reeling&&elapsed<12){g.ReelStep(g.tension<.7f,Time.deltaTime);elapsed+=Time.deltaTime;yield return null;}Check(g.bag.Count==before+1&&g.fishing==FishingState.Idle,"Fishing completes through reel progress and tension");
   g.CancelFishing("Verification");g.quickBite=0;g.slowBite=0;g.CastAt(new Vector3(0,-.2f,40));g.biteAt=Time.time;yield return null;g.biteDeadline=Time.time-.1f;yield return null;Check(g.fishing==FishingState.Idle&&!g.line.enabled,"Missed bite clears line and resets fishing");
   var timed=g.gifts;timed.Clear();timed.Trigger("visual/slow_motion",.25f,.5f);yield return null;Check(Mathf.Abs(Time.timeScale-.5f)<.01f,"Slow motion applied live");yield return new WaitForSecondsRealtime(.45f);Check(Mathf.Abs(Time.timeScale-1)<.01f,"Slow motion expires in real time and restores time scale");
   var pos=g.world.boat.position;g.world.boatImpulse=Vector3.forward*12;yield return new WaitForSecondsRealtime(.3f);Check(Vector3.Distance(g.world.boat.position,pos)>.5f,"Boat impulse physically moves boat");
   g.Respawn();g.ui.panel=false;g.automationMove=Vector3.forward;var start=g.body.transform.position;yield return new WaitForSecondsRealtime(.3f);float normalMove=g.body.transform.position.z-start.z;Check(normalMove>.8f&&normalMove<1.6f,"Walk input moves controller at baseline speed");g.Teleport(start);g.gifts.Trigger("movement/speed_boost",5,2);yield return new WaitForSecondsRealtime(.3f);Check(g.body.transform.position.z-start.z>normalMove*1.7f,"Speed gift increases physical travel distance");g.gifts.Clear();g.Teleport(start);g.gifts.Trigger("controls/reverse",5);yield return new WaitForSecondsRealtime(.3f);Check(g.body.transform.position.z<start.z-.7f,"Reverse gift reverses physical travel direction");g.gifts.Clear();g.Teleport(start);g.gifts.Trigger("player/freeze",5);g.impulse=Vector3.forward*10;yield return new WaitForSecondsRealtime(.3f);Check(Mathf.Abs(g.body.transform.position.z-start.z)<.05f,"Freeze blocks movement and external impulse");g.gifts.Clear();g.automationMove=Vector3.zero;g.gifts.Trigger("controls/force_crouch",5);yield return new WaitForSecondsRealtime(.4f);Check(g.cam.transform.localPosition.y<1.12f&&g.body.height<1.2f,"Forced crouch changes actual camera and capsule");g.gifts.Clear();yield return new WaitForSecondsRealtime(.4f);Check(g.cam.transform.localPosition.y>1.5f&&g.body.height>1.7f,"Crouch expiration restores view and capsule");
   g.Respawn();var dropped=g.SpawnFish(new Vector3(0,3,25),1,false,false);yield return new WaitForSecondsRealtime(1);Check(dropped.transform.position.y>1.3f,"Dropped fish rests on actual pier collider");var life=g.health;g.gifts.Trigger("status/ignite",2);yield return new WaitForSecondsRealtime(1.2f);Check(g.health<life,"Ignite deals damage through live tick");g.gifts.Trigger("status/cleanse");life=g.health;yield return new WaitForSecondsRealtime(1.1f);Check(g.health==life,"Cleanse stops further ailment damage");
   var opponent=g.SpawnFish(g.cam.transform.position+Vector3.forward*10,4,false,true);g.yaw=g.pitch=0;g.SetTool(1);g.ammo=12;yield return new WaitForSecondsRealtime(.3f);var hp=opponent.health;g.Shoot();Check(opponent.health<hp,"Rifle raycast damages live boss collider");yield return new WaitForSecondsRealtime(.3f);g.gifts.Trigger("weapon/max_recoil",2,4);float aim=g.pitch;g.Shoot();Check(aim-g.pitch>4,"Maximum recoil changes actual camera pitch");g.gifts.Clear();opponent.Remove();g.Respawn();g.SetTool(0);g.ui.panel=true;g.ui.Select(GiftCatalog.Find("chaos/spawn_fish"));g.Notice("自动回归已完成，正在采集画面");yield return new WaitForSecondsRealtime(.2f);Capture("verification-harbor.png");yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(output,"verification-panel.png"));yield return null;
   var save=new SaveData{coins=123,bait=7,landed=2,bag=new List<CatchData>{new(){species="Test",weight=3,price=36,drip=true,cooked=true}}};var path=Path.Combine(output,"isolated-save-test.json");File.WriteAllText(path,JsonUtility.ToJson(save));var loaded=JsonUtility.FromJson<SaveData>(File.ReadAllText(path));Check(loaded.coins==123&&loaded.bag.Count==1&&loaded.bag[0].cooked,"Isolated save serialization roundtrip");
   results.Insert(0,"Engine "+Application.unityVersion+" | "+DateTime.UtcNow.ToString("O"));results.Insert(1,"Assertions "+results.Count+"; failures "+failed);File.WriteAllLines(Path.Combine(output,"runtime-verification.txt"),results);finished=true;Debug.Log("FISH_VERIFY_COMPLETE failures="+failed);Application.Quit(failed==0?0:1);
  }
  void ResetFixture(){g.gifts.Clear();g.dead=false;g.health=60;g.fullness=60;g.coins=1000;g.bait=10;g.ammo=6;g.vertical=0;g.impulse=Vector3.zero;g.driving=false;g.CancelFishing("fixture");g.bag.Clear();g.held=new CatchData{species="Test",weight=2,price=24};g.bag.Add(g.held);g.ShowHeld();g.nextDrip=g.nextHeavy=g.nextSale=g.lineGuard=g.quickBite=g.slowBite=0;g.SetTool(0);g.Teleport(new Vector3(0,1.35f,21));g.yaw=0;g.pitch=0;g.world.boat.position=new Vector3(5,.2f,29);g.world.boatImpulse=Vector3.zero;g.world.boatSpin=0;foreach(var e in g.entities.ToArray())if(e)Destroy(e.gameObject);g.entities.Clear();g.boss=null;}
  void RunLogic(){Check(GiftCatalog.All.Count==56,"All 56 original event IDs have definitions");Check(GiftCatalog.All.Select(x=>x.id).Distinct().Count()==56,"Event IDs are unique");var catalogPath=Path.Combine(output,"original-event-ids.txt");if(File.Exists(catalogPath)){var ids=File.ReadAllLines(catalogPath).Where(x=>x.Length>0).ToArray();Check(ids.Length==56&&ids.All(x=>GiftCatalog.Find(x)!=null),"Exact event ID parity with original plugin static evidence");}
   foreach(var d in GiftCatalog.All){ResetFixture();if(d.id=="boss/heal"){var b=g.SpawnFish(new Vector3(0,5,35),4,false,true);b.health=100;}int entities=g.entities.Count;bool ok=g.gifts.Trigger(d.id);Check(ok,d.id+" accepted");if(d.duration>0){Check(g.gifts.Has(d.id),d.id+" activates timed channel");g.gifts.Tick(d.duration+.1f);Check(!g.gifts.Has(d.id),d.id+" expires");continue;}
    bool state=d.id switch{
     "money/add"=>g.coins==1500,"money/remove"=>g.coins==750,"player/heal"=>g.health==85,"player/damage"=>g.health==40,"player/feed"=>g.fullness==85,"player/hunger"=>g.fullness==35,
     "player/return_to_spawn"=>Vector3.Distance(g.body.transform.position,new Vector3(0,1.35f,21))<.01f,"chaos/launch"=>g.vertical==24,"inventory/drop_all"=>g.bag.Count==0&&g.entities.Count==1,
     "chaos/yeet_held_item"=>g.entities.Any(x=>x.kind==EntityKind.Tool&&x.velocity.magnitude>20),"chaos/cook_held_fish"=>g.held.cooked&&g.held.price==36,"chaos/random_skin"=>g.rod.GetComponentsInChildren<Renderer>().Length>0,
     "weapon/refill_ammo"=>g.ammo==12,"weapon/empty_mag"=>g.ammo==0,"bait/refill"=>g.bait==15,"loot/next_drip"=>g.nextDrip==1,"loot/next_heavy_fish"=>g.nextHeavy==1&&g.nextWeight==3,"economy/next_sale_boost"=>g.nextSale==1&&g.nextPayout==2,
     "fishing/quick_bite"=>g.quickBite==1,"fishing/slow_bite"=>g.slowBite==1&&g.nextDelay==2,"fishing/line_guard"=>g.lineGuard==1,"birds/protect_catch"=>!g.entities.Any(x=>x.kind==EntityKind.Bird),"birds/raid"=>g.entities.Any(x=>x.kind==EntityKind.Bird),"boss/heal"=>g.boss.health==130,
     "chaos/spawn_item"=>g.entities.Any(x=>x.kind==EntityKind.Item),"chaos/dynamite"=>g.entities.Any(x=>x.kind==EntityKind.Dynamite&&x.life==3),"chaos/boat_boost"=>g.world.boatImpulse.magnitude==18,"chaos/boat_spin"=>g.world.boatSpin==360,
     "chaos/spawn_boss"=>g.boss&&g.boss.health==300,"chaos/spawn_drip_fish"=>g.entities.Any(x=>x.catchData!=null&&x.catchData.drip),"chaos/spawn_giant_fish"=>g.entities.Any(x=>x.GetComponent<SphereCollider>().radius>1.9f),"chaos/spawn_tiny_fish"=>g.entities.Any(x=>x.GetComponent<SphereCollider>().radius<.3f),"chaos/spawn_fish"=>g.entities.Count==entities+1,"status/cleanse"=>!g.gifts.Has("status/ignite")&&!g.gifts.Has("status/poison"),_=>false};Check(state,d.id+" expected state mutation");
   }
   ResetFixture();g.gifts.Trigger("movement/speed_boost",2,2);g.gifts.Trigger("movement/slow",3,.5f);Check(g.gifts.Has("movement/speed_boost")&&!g.gifts.Has("movement/slow")&&g.gifts.QueueCount("movement")==1,"Conflicting movement effects queue without multiplying");g.gifts.Tick(2.1f);Check(!g.gifts.Has("movement/speed_boost")&&g.gifts.Has("movement/slow"),"Queued movement effect promotes");g.gifts.Tick(3.1f);Check(g.gifts.active.Count==0&&g.gifts.Value("movement/slow")==1,"Movement channel restores baseline");
   g.gifts.Trigger("visual/slow_motion",2,.5f);g.gifts.Trigger("visual/speed_up",2,1.5f);g.gifts.Tick(.01f);Check(Time.timeScale==.5f,"Time effects share conflict channel");g.gifts.Tick(2);Check(Time.timeScale==1.5f,"Queued time acceleration promotes");g.gifts.Clear();Check(Time.timeScale==1&&Mathf.Abs(Time.fixedDeltaTime-.02f)<.00001f,"Clear restores time and physics delta");
   g.gifts.Trigger("status/ignite");g.gifts.Trigger("status/poison");g.gifts.Trigger("status/cleanse");Check(!g.gifts.Has("status/ignite")&&!g.gifts.Has("status/poison"),"Cleanse removes both ailments");Check(!g.gifts.Trigger("unknown/gift"),"Unknown event rejected");Check(!g.gifts.Trigger("boss/heal"),"Boss heal has prerequisite error");
   g.gifts.Trigger("fishing/slow_bite");g.gifts.Trigger("fishing/quick_bite");g.CastAt(new Vector3(0,-.2f,40));Check(g.biteAt-Time.time>=7.9f&&g.quickBite==1&&g.slowBite==0,"Bite effects consume in FIFO order");g.CancelFishing("test");g.CastAt(new Vector3(0,-.2f,40));Check(g.biteAt-Time.time<.2f&&g.quickBite==0,"Queued quick bite applies to subsequent cast");g.CancelFishing("test");g.gifts.Trigger("loot/next_drip");g.gifts.Clear();Check(g.nextDrip==0&&g.biteQueue.Count==0,"Restore-all clears pending one-shot effects");
   g.gifts.Trigger("economy/next_sale_boost");int before=g.coins;Check(g.Sell()==48&&g.coins==before+48&&g.nextSale==0,"Next-sale multiplier consumed exactly once");Check(g.Sell()==0&&g.coins==before+48,"Empty sale cannot duplicate reward");
   g.nextDrip=1;g.nextHeavy=1;g.nextWeight=3;g.LandFish();Check(g.held.drip&&g.held.weight>=1.5f&&g.nextDrip==0&&g.nextHeavy==0,"Catch consumes next-drip and next-heavy once");g.Cook();float fullness=g.fullness;g.Eat();Check(g.fullness>fullness&&g.bag.Count==0,"Cooked fish eaten and removed from inventory");
   g.ammo=2;g.Shoot();Check(g.ammo==1&&g.shotCount==1,"Shooting consumes one bullet");g.ammo=0;g.Shoot();Check(g.ammo==0,"Empty weapon cannot fire");
   var bird=g.SpawnEntity(EntityKind.Bird,new Vector3(0,6,25));g.gifts.Trigger("birds/protect_catch");Check(!g.entities.Contains(bird),"Bird protection removes actual raider");var b2=g.SpawnFish(new Vector3(0,5,35),4,false,true);before=g.coins;b2.Hit(400);Check(g.coins==before+200&&!g.entities.Contains(b2),"Boss death rewards coins and despawns boss");
   g.gifts.Trigger("movement/speed_boost");g.Damage(100);Check(g.dead&&g.gifts.active.Count==0,"Death clears active effects");Check(!g.gifts.Trigger("money/add"),"Dead players reject gifts");g.Respawn();Check(!g.dead&&g.health==100,"Respawn restores playable state");ResetFixture();g.health=100;g.fullness=100;
  }
  void Capture(string name){var rt=new RenderTexture(1280,720,24);var previous=g.cam.targetTexture;g.cam.targetTexture=rt;g.cam.Render();var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes(Path.Combine(output,name),image.EncodeToPNG());g.cam.targetTexture=previous;RenderTexture.active=old;rt.Release();Destroy(image);Destroy(rt);}
  void OnDestroy(){if(!finished&&results.Count>0){try{File.WriteAllLines(Path.Combine(output,"runtime-verification-interrupted.txt"),results);}catch{}}}
 }
}

